package com.receiptledger.v1;

import android.app.Activity;import android.os.Bundle;import android.widget.*;import com.receiptledger.v1.design.UiKitV1;import com.receiptledger.v1.persistence.SqliteReceiptStore;import com.receiptledger.v1.price.*;import com.receiptledger.v1.product.*;import com.receiptledger.v1.ui.SystemBarInsetHelper;import java.util.*;import java.util.concurrent.*;

public final class PriceHistoryActivity extends Activity {
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private SqliteReceiptStore receipts;private SqliteProductCatalogStore catalog;private PriceHistoryService service;private LinearLayout products;private TextView detail,status;private long generation;
 @Override protected void onCreate(Bundle b){super.onCreate(b);receipts=new SqliteReceiptStore(getApplicationContext());catalog=new SqliteProductCatalogStore(getApplicationContext());service=new PriceHistoryService(receipts,catalog);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);UiKitV1.applyPage(this,root);TextView title=UiKitV1.title(this,R.string.price_history_title);status=UiKitV1.status(this);ScrollView productScroll=new ScrollView(this);products=new LinearLayout(this);products.setOrientation(LinearLayout.VERTICAL);productScroll.addView(products);detail=UiKitV1.body(this,"");detail.setTextIsSelectable(true);ScrollView detailScroll=new ScrollView(this);detailScroll.addView(detail);Button close=UiKitV1.button(this,R.string.close_library,v->finish(),UiKitV1.ButtonTone.SECONDARY);root.addView(title);root.addView(close);root.addView(status);root.addView(productScroll,new LinearLayout.LayoutParams(-1,0,0.38f));root.addView(detailScroll,new LinearLayout.LayoutParams(-1,0,0.62f));setContentView(root);SystemBarInsetHelper.apply(this,root);loadProducts();}
 private void loadProducts(){long t=++generation;worker.execute(()->{List<CatalogProduct> list=catalog.listProducts();runOnUiThread(()->{if(t!=generation)return;products.removeAllViews();status.setText(getString(R.string.price_product_count,list.size()));for(CatalogProduct p:list){Button b=UiKitV1.listRow(this,getString(R.string.price_product_button,p.type,p.canonicalName),v->loadHistory(p.id));products.addView(b);}});});}
 private void loadHistory(String productId){long t=++generation;status.setText(R.string.price_loading);worker.execute(()->{try{PriceHistory h=service.history(productId);runOnUiThread(()->{if(t==generation){detail.setText(PriceHistoryFormatter.format(h));status.setText(getString(R.string.price_observation_count,h.observations.size()));}});}catch(Exception e){runOnUiThread(()->{if(t==generation)status.setText(e.getMessage());});}});}
 @Override protected void onDestroy(){generation++;worker.shutdownNow();catalog.close();receipts.close();super.onDestroy();}
}
